BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
DO $guard$
BEGIN
 IF to_regclass('public."Feature04_Technical_Indicator"') IS NOT NULL THEN
  RAISE EXCEPTION 'Feature04_Technical_Indicator exists; stop for inspection, no conflicting changes';
 END IF;
 IF to_regclass('public."Price_Stock_Indonesia_IDX"') IS NULL THEN
  RAISE EXCEPTION 'Verified source table is absent';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public."Price_Stock_Indonesia_IDX"'::regclass AND contype='p' AND pg_get_constraintdef(oid)='PRIMARY KEY (ticker, date)') THEN
  RAISE EXCEPTION 'Verified source grain changed';
 END IF;
 IF EXISTS(SELECT 1 FROM public."Price_Stock_Indonesia_IDX" WHERE timeframe<>'Daily' OR source<>'TradingView' OR tradingview_symbol<>'IDX:'||ticker) THEN
  RAISE EXCEPTION 'Source dimensions/mapping differ from inspection';
 END IF;
 IF EXISTS(SELECT 1 FROM (VALUES ('ticker','varchar'),('date','date'),('timeframe','varchar'),('open','numeric'),('high','numeric'),('low','numeric'),('close','numeric'),('volume','numeric')) AS expected(name,udt)
  LEFT JOIN information_schema.columns c ON c.table_schema='public' AND c.table_name='Price_Stock_Indonesia_IDX' AND c.column_name=expected.name
  WHERE c.column_name IS NULL OR c.udt_name<>expected.udt OR c.is_nullable<>'NO') THEN
  RAISE EXCEPTION 'Verified source column contract changed';
 END IF;
END $guard$;
CREATE TABLE public."Feature04_Technical_Indicator" (
 "ticker" text NOT NULL,
 "trade_date" date NOT NULL,
 "timeframe" text NOT NULL,
 "sma_20" double precision,
 "sma_50" double precision,
 "ema_12" double precision,
 "ema_26" double precision,
 "rsi_14" double precision,
 "macd" double precision,
 "macd_signal" double precision,
 "macd_histogram" double precision,
 "atr_14" double precision,
 "bb_upper_20" double precision,
 "bb_middle_20" double precision,
 "bb_lower_20" double precision,
 "cdl_piercing" integer,
 "cdl_morning_star" integer,
 "cdl_morning_doji_star" integer,
 "cdl_engulfing" integer,
 "cdl_3_white_soldiers" integer,
 "cdl_hammer" integer,
 "cdl_inverted_hammer" integer,
 "cdl_3_inside" integer,
 "cdl_3_outside" integer,
 "cdl_harami" integer,
 "cdl_harami_cross" integer,
 "cdl_dark_cloud_cover" integer,
 "cdl_evening_star" integer,
 "cdl_evening_doji_star" integer,
 "cdl_3_black_crows" integer,
 "cdl_shooting_star" integer,
 "cdl_hanging_man" integer,
 "cdl_doji" integer,
 "cdl_dragonfly_doji" integer,
 "cdl_gravestone_doji" integer,
 "cdl_marubozu" integer,
 "cdl_kicking" integer,
 "cdl_rise_fall_3_methods" integer,
 "cdl_mat_hold" integer,
 "cdl_hikkake" integer,
 "calculation_version" text NOT NULL,
 "calculated_at" timestamptz NOT NULL,
 CONSTRAINT "Feature04_Technical_Indicator_pkey" PRIMARY KEY(ticker,trade_date,timeframe),
 CHECK(ticker=upper(btrim(ticker)) AND ticker<>''),
 CHECK(timeframe='Daily'),
 CHECK(btrim(calculation_version)<>''),
 CHECK("sma_20" IS NULL OR ("sma_20">'-Infinity'::double precision AND "sma_20"<'Infinity'::double precision)),
 CHECK("sma_50" IS NULL OR ("sma_50">'-Infinity'::double precision AND "sma_50"<'Infinity'::double precision)),
 CHECK("ema_12" IS NULL OR ("ema_12">'-Infinity'::double precision AND "ema_12"<'Infinity'::double precision)),
 CHECK("ema_26" IS NULL OR ("ema_26">'-Infinity'::double precision AND "ema_26"<'Infinity'::double precision)),
 CHECK("rsi_14" IS NULL OR ("rsi_14">'-Infinity'::double precision AND "rsi_14"<'Infinity'::double precision)),
 CHECK("macd" IS NULL OR ("macd">'-Infinity'::double precision AND "macd"<'Infinity'::double precision)),
 CHECK("macd_signal" IS NULL OR ("macd_signal">'-Infinity'::double precision AND "macd_signal"<'Infinity'::double precision)),
 CHECK("macd_histogram" IS NULL OR ("macd_histogram">'-Infinity'::double precision AND "macd_histogram"<'Infinity'::double precision)),
 CHECK("atr_14" IS NULL OR ("atr_14">'-Infinity'::double precision AND "atr_14"<'Infinity'::double precision)),
 CHECK("bb_upper_20" IS NULL OR ("bb_upper_20">'-Infinity'::double precision AND "bb_upper_20"<'Infinity'::double precision)),
 CHECK("bb_middle_20" IS NULL OR ("bb_middle_20">'-Infinity'::double precision AND "bb_middle_20"<'Infinity'::double precision)),
 CHECK("bb_lower_20" IS NULL OR ("bb_lower_20">'-Infinity'::double precision AND "bb_lower_20"<'Infinity'::double precision)),
 CHECK(rsi_14 IS NULL OR rsi_14 BETWEEN 0 AND 100),
 CHECK(atr_14 IS NULL OR atr_14>=0)
);
COMMENT ON TABLE public."Feature04_Technical_Indicator" IS 'Daily IDX wide technical features; 42 columns; full-history causal TA-Lib initialization. TradingView numerical parity and point-in-time training eligibility NOT VERIFIED. No automatic writer deployed.';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."ticker" IS 'IDX security code copied from source ticker. ticker';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."trade_date" IS 'Trading observation date copied from source date. date';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."timeframe" IS 'Verified daily timeframe copied exactly from source. timeframe = Daily';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."sma_20" IS 'Unweighted mean of 20 observed closes. TA-Lib SMA(close,20)';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."sma_50" IS 'Unweighted mean of 50 observed closes. TA-Lib SMA(close,50)';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."ema_12" IS 'Fast exponentially weighted close; alpha=2/13. Seed=SMA(first12 closes); EMA[t]=EMA[t-1]+2/13*(close[t]-EMA[t-1])';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."ema_26" IS 'Slow exponentially weighted close; alpha=2/27. Seed=SMA(first26 closes); EMA[t]=EMA[t-1]+2/27*(close[t]-EMA[t-1])';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."rsi_14" IS 'Wilder gain/loss oscillator on 14 consecutive close changes, scaled 0–100. TA-Lib RSI(close,14): SMA seed of 14 gains/losses; RMA alpha=1/14; 100*gain/(gain+loss); both-zero uses native 0';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."macd" IS 'Difference of the stored fast and slow EMA price baselines. ema_12 - ema_26; independently SMA-seeded EMAs, not TA-Lib MACD internal fast reseeding';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."macd_signal" IS 'Nine-period EMA of valid MACD line observations. Seed=SMA(first9 valid macd); signal[t]=signal[t-1]+0.2*(macd[t]-signal[t-1])';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."macd_histogram" IS 'Difference between MACD line and its nine-period signal. macd - macd_signal';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."atr_14" IS 'Wilder average of 14 true ranges using prior observed close. TA-Lib ATR(high,low,close,14): TR=max(high-low,abs(high-prev_close),abs(low-prev_close)); first TR excludes bar1; SMA seed then RMA alpha=1/14';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."bb_upper_20" IS 'Upper 20-period Bollinger band, population standard deviation multiplier 2. SMA20(close) + 2*sqrt(sum((close-SMA20)^2)/20)';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."bb_middle_20" IS 'Middle 20-period Bollinger band, identical to SMA20. SMA20(close)';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."bb_lower_20" IS 'Lower 20-period Bollinger band, population standard deviation multiplier 2. SMA20(close) - 2*sqrt(sum((close-SMA20)^2)/20)';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_piercing" IS 'Native TA-Lib piercing pattern recognition code from historical OHLC. TA-Lib CDLPIERCING(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_morning_star" IS 'Native TA-Lib morning star pattern recognition code from historical OHLC. TA-Lib CDLMORNINGSTAR(open,high,low,close), default candle settings; parameters={''penetration'': 0.3}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_morning_doji_star" IS 'Native TA-Lib morning doji star pattern recognition code from historical OHLC. TA-Lib CDLMORNINGDOJISTAR(open,high,low,close), default candle settings; parameters={''penetration'': 0.3}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_engulfing" IS 'Native TA-Lib engulfing pattern recognition code from historical OHLC. TA-Lib CDLENGULFING(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_3_white_soldiers" IS 'Native TA-Lib 3 white soldiers pattern recognition code from historical OHLC. TA-Lib CDL3WHITESOLDIERS(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_hammer" IS 'Native TA-Lib hammer pattern recognition code from historical OHLC. TA-Lib CDLHAMMER(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_inverted_hammer" IS 'Native TA-Lib inverted hammer pattern recognition code from historical OHLC. TA-Lib CDLINVERTEDHAMMER(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_3_inside" IS 'Native TA-Lib 3 inside pattern recognition code from historical OHLC. TA-Lib CDL3INSIDE(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_3_outside" IS 'Native TA-Lib 3 outside pattern recognition code from historical OHLC. TA-Lib CDL3OUTSIDE(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_harami" IS 'Native TA-Lib harami pattern recognition code from historical OHLC. TA-Lib CDLHARAMI(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_harami_cross" IS 'Native TA-Lib harami cross pattern recognition code from historical OHLC. TA-Lib CDLHARAMICROSS(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_dark_cloud_cover" IS 'Native TA-Lib dark cloud cover pattern recognition code from historical OHLC. TA-Lib CDLDARKCLOUDCOVER(open,high,low,close), default candle settings; parameters={''penetration'': 0.5}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_evening_star" IS 'Native TA-Lib evening star pattern recognition code from historical OHLC. TA-Lib CDLEVENINGSTAR(open,high,low,close), default candle settings; parameters={''penetration'': 0.3}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_evening_doji_star" IS 'Native TA-Lib evening doji star pattern recognition code from historical OHLC. TA-Lib CDLEVENINGDOJISTAR(open,high,low,close), default candle settings; parameters={''penetration'': 0.3}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_3_black_crows" IS 'Native TA-Lib 3 black crows pattern recognition code from historical OHLC. TA-Lib CDL3BLACKCROWS(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_shooting_star" IS 'Native TA-Lib shooting star pattern recognition code from historical OHLC. TA-Lib CDLSHOOTINGSTAR(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_hanging_man" IS 'Native TA-Lib hanging man pattern recognition code from historical OHLC. TA-Lib CDLHANGINGMAN(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_doji" IS 'Native TA-Lib doji pattern recognition code from historical OHLC. TA-Lib CDLDOJI(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_dragonfly_doji" IS 'Native TA-Lib dragonfly doji pattern recognition code from historical OHLC. TA-Lib CDLDRAGONFLYDOJI(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_gravestone_doji" IS 'Native TA-Lib gravestone doji pattern recognition code from historical OHLC. TA-Lib CDLGRAVESTONEDOJI(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_marubozu" IS 'Native TA-Lib marubozu pattern recognition code from historical OHLC. TA-Lib CDLMARUBOZU(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_kicking" IS 'Native TA-Lib kicking pattern recognition code from historical OHLC. TA-Lib CDLKICKING(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_rise_fall_3_methods" IS 'Native TA-Lib rise fall 3 methods pattern recognition code from historical OHLC. TA-Lib CDLRISEFALL3METHODS(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_mat_hold" IS 'Native TA-Lib mat hold pattern recognition code from historical OHLC. TA-Lib CDLMATHOLD(open,high,low,close), default candle settings; parameters={''penetration'': 0.5}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."cdl_hikkake" IS 'Native TA-Lib hikkake pattern recognition code from historical OHLC. TA-Lib CDLHIKKAKE(open,high,low,close), default candle settings; parameters={}; native signed integers including non-100 codes retained';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."calculation_version" IS 'Version binds formulas, seeds and pinned TA-Lib versions. engine.VERSION';
COMMENT ON COLUMN public."Feature04_Technical_Indicator"."calculated_at" IS 'Timezone-aware execution time of the last changed output row. UTC execution timestamp; unchanged UPSERT preserves existing timestamp';
