DO $validator_guard$ BEGIN IF md5(pg_get_functiondef('public.validate_feature_catalog_target()'::regprocedure)) <> md5('CREATE OR REPLACE FUNCTION public.validate_feature_catalog_target()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.is_active THEN
        IF NEW.feature_table !~ ''^Feature_[0-9]{2}_[A-Za-z0-9_]+$'' THEN
            RAISE EXCEPTION ''Active Feature table name % is not governed'', NEW.feature_table;
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema = ''public'' AND table_name = NEW.feature_table
              AND column_name = NEW.feature_column
        ) THEN
            RAISE EXCEPTION ''Active catalog target %.% does not exist'',
                NEW.feature_table, NEW.feature_column;
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM public."Table_Catalog"
            WHERE table_schema = ''public'' AND table_name = NEW.feature_table
              AND category = ''Feature'' AND documentation_status = ''VERIFIED''
        ) THEN
            RAISE EXCEPTION ''Active Feature table % is not VERIFIED in Table_Catalog'',
                NEW.feature_table;
        END IF;
    END IF;
    RETURN NEW;
END
$function$
') THEN RAISE EXCEPTION 'Catalog validator changed since inspection'; END IF; END $validator_guard$;
CREATE OR REPLACE FUNCTION public.validate_feature_catalog_target()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.is_active THEN
        IF NEW.feature_table !~ '^Feature_[0-9]{2}_[A-Za-z0-9_]+$' AND NEW.feature_table <> 'Feature04_Technical_Indicator' THEN
            RAISE EXCEPTION 'Active Feature table name % is not governed', NEW.feature_table;
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema = 'public' AND table_name = NEW.feature_table
              AND column_name = NEW.feature_column
        ) THEN
            RAISE EXCEPTION 'Active catalog target %.% does not exist',
                NEW.feature_table, NEW.feature_column;
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM public."Table_Catalog"
            WHERE table_schema = 'public' AND table_name = NEW.feature_table
              AND category = 'Feature' AND documentation_status = 'VERIFIED'
        ) THEN
            RAISE EXCEPTION 'Active Feature table % is not VERIFIED in Table_Catalog',
                NEW.feature_table;
        END IF;
    END IF;
    RETURN NEW;
END
$function$;
UPDATE public."Table_Catalog" SET related_functions=array_append(related_functions,'public.validate_feature_catalog_target()'),updated_at=clock_timestamp() WHERE table_schema='public' AND table_name IN ('Feature_Catalog','Feature04_Technical_Indicator') AND NOT ('public.validate_feature_catalog_target()'=ANY(related_functions));
